31	/**
32	 * Retrieves and validates an invitation by its token.
33	 *
34	 * @param token - The invitation token to validate.
35	 * @param deps - The dependencies providing access to invitation and player
36	 * email services.
37	 * @returns The valid invitation object associated with the provided token.
38	 * @throws If the token is missing, the invitation is not found, expired,
39	 * already used, lacks a player reference, or the email is already associated
40	 * with a different player.
41	 */
42	async function getValidInvitation(token: string, deps: ClaimPlayerInvitationDeps) {
43	    if (!token) {
44	        throw new ValidationError('Missing invitation token.', {
45	            publicMessage: 'This invitation link is invalid.',
46	        });
47	    }
48	
49	    const invitation = await deps.emailVerificationService.getByToken(token);
50	
51	    if (!invitation) {
52	        throw new NotFoundError('Invitation not found or expired.', {
53	            publicMessage: 'This invitation link is invalid or has expired.',
54	        });
55	    }
56	
57	    if (invitation.usedAt) {
58	        throw new ConflictError('Invitation has already been used.', {
59	            publicMessage: 'This invitation has already been used.',
60	        });
61	    }
62	    if (invitation.expiresAt <= new Date()) {
63	        throw new ConflictError('Invitation has expired.', {
64	            publicMessage: 'This invitation has expired.',
65	        });
66	    }
67	
68	    if (!invitation.playerId) {
69	        throw new ValidationError('Invitation is missing a player reference.', {
70	            publicMessage: 'This invitation link is invalid.',
71	        });
72	    }
73	
74	    const existingExtraEmail = await deps.playerExtraEmailService.getByEmail(invitation.email);
75	    if (existingExtraEmail && existingExtraEmail.playerId !== invitation.playerId) {
76	        throw new ConflictError('Email address already belongs to another player.', {
77	            publicMessage: 'This email address is already associated with a different player.',
78	        });
79	    }
80	
81	    return invitation;
82	}
83	
84	/**
85	 * Claims a player invitation using the provided token and returns essential
86	 * player information.
87	 *
88	 * Validates the invitation token, ensures the invitation includes a `playerId`,
89	 * retrieves the corresponding player, and returns a summary payload containing
90	 * the player's name, the invitation email, and the original token.
91	 *
92	 * @param token - The invitation token to validate and claim.
93	 * @param deps - Optional dependencies required for validation and data
94	 * retrieval. Defaults to `defaultDeps`.
95	 * @returns An object containing:
96	 * - `name`: The player's display name.
97	 * - `email`: The email address associated with the invitation.
98	 * - `token`: The original invitation token passed in.
99	 *
100	 * @throws {Error} If no player exists for the given `playerId`.
101	 * @throws {Error} Propagates errors from invitation validation (e.g., invalid
102	 * or expired token).
103	 */
104	export async function claimPlayerInvitationCore(
105	    token: string,
106	    deps: ClaimPlayerInvitationDeps = defaultDeps,
107	) {
108	    const invitation = await getValidInvitation(token, deps);
109	
110	    const player = await deps.playerService.getById(invitation.playerId!);
111	
112	    if (!player) {
113	        throw new NotFoundError('Player not found.', {
114	            publicMessage: 'This invitation link is invalid.',
115	        });
116	    }
117	
118	    return {
119	        name: player.name,
120	        email: invitation.email,
121	        token,
122	    };
123	}
124	
125	/**
126	 * Finalizes the claim of a player invitation by linking the current user's
127	 * account to the player.
128	 *
129	 * This function performs the following operations:
130	 * 1. Validates the invitation token
131	 * 2. Verifies the session user exists and their email matches the invitation
132	 * 3. Ensures the user account is not already linked to a different player
133	 * 4. Links the current user to the player
134	 * 5. Updates the player with the account email
135	 * 6. Marks the invitation token as used
136	 * 7. Sends verification emails for any unverified extra emails associated with
137	 *    the player
138	 *
139	 * @param token - The invitation token to validate and process
140	 * @param deps - Optional dependencies object containing services for auth,
141	 * player management, email verification, and email sending. Uses default
142	 * dependencies if not provided.
143	 *
144	 * @throws {Error} If the invitation is invalid
145	 * @throws {Error} If no session user is found or the user email/ID is missing
146	 * @throws {Error} If the session user's email does not match the invitation
147	 * email
148	 * @throws {Error} If the session user account is already linked to a different
149	 * player
150	 *
151	 * @returns A promise that resolves when the invitation claim process is
152	 * complete
153	 */
154	export async function finalizePlayerInvitationClaimCore(
155	    token: string,
156	    deps: ClaimPlayerInvitationDeps = defaultDeps,
157	) {
158	    const invitation = await getValidInvitation(token, deps);
159	
160	    const sessionUser = await deps.authService.getSessionUser();
161	
162	    if (!sessionUser?.id || !sessionUser.email) {
163	        throw new AuthError('Login account not found for invitation.');
164	    }
165	
166	    if (sessionUser.email.toLowerCase() !== invitation.email.toLowerCase()) {
167	        throw new AuthError('Login account email does not match invitation.');
168	    }
169	
170	    if (sessionUser.playerId && sessionUser.playerId !== invitation.playerId) {
171	        throw new ConflictError('Login account is already linked to another player.');
172	    }
173	
174	    await deps.authService.updateCurrentUser({ playerId: invitation.playerId! });
175	    await deps.playerService.update({
176	        id: invitation.playerId!,
177	        accountEmail: invitation.email,
178	    });
179	    await deps.emailVerificationService.markUsed(token);
180	
181	    const extraEmails = await deps.playerExtraEmailService.getAll(invitation.playerId!);
182	    const unverifiedExtraEmails = extraEmails.filter((extraEmail) => !extraEmail.verifiedAt);
183	    const player = await deps.playerService.getById(invitation.playerId!);
184	
185	    await Promise.all(
186	        unverifiedExtraEmails.map((extraEmail) =>
187	            deps.sendEmailVerification(extraEmail.email, player ?? undefined),
188	        ),
189	    );
190	}
